using System;
using UnityEngine;

namespace EyeCamXR
{
    [Serializable]
    class TargetJson
    {
        public int w;
        public int h;
        public string grid; // base64 little-endian float64, row-major
    }

    /// <summary>
    /// Loads target luminance grids from Resources/Targets/&lt;name&gt;.json
    /// (generated by gen_targets.py with the exact laptop-stack rendering) and
    /// resamples to the session grid with the same nearest/box logic PIL's
    /// LANCZOS approximates at these tiny sizes — for parity-critical work the
    /// JSON is generated at the session grid size directly.
    /// </summary>
    public static class TargetProvider
    {
        public static double[,] Load(string name, int gridW, int gridH)
        {
            var ta = Resources.Load<TextAsset>($"Targets/{name}_{gridW}x{gridH}")
                     ?? Resources.Load<TextAsset>($"Targets/{name}");
            if (ta == null)
            {
                Debug.LogWarning($"[EyeCam] target '{name}' missing, using checker");
                return Checker(gridW, gridH);
            }
            var tj = JsonUtility.FromJson<TargetJson>(ta.text);
            var bytes = Convert.FromBase64String(tj.grid);
            var flat = new double[bytes.Length / 8];
            Buffer.BlockCopy(bytes, 0, flat, 0, bytes.Length);

            var src = new double[tj.h, tj.w];
            int i = 0;
            for (int y = 0; y < tj.h; y++)
                for (int x = 0; x < tj.w; x++) src[y, x] = flat[i++];
            if (tj.w == gridW && tj.h == gridH) return src;

            // nearest resample fallback
            var dst = new double[gridH, gridW];
            for (int y = 0; y < gridH; y++)
                for (int x = 0; x < gridW; x++)
                    dst[y, x] = src[y * tj.h / gridH, x * tj.w / gridW];
            return dst;
        }

        static double[,] Checker(int w, int h)
        {
            var g = new double[h, w];
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                    g[y, x] = ((x / 2 + y / 2) % 2 == 0) ? 1.0 : 0.0;
            return g;
        }
    }
}
